async function ai(){var chainId=window._interactionChainId||'';if(!chainId){ct.innerHTML='<div class="card"><h3>交互详情</h3><p style="color:var(--muted);text-align:center;padding:30px">请先从「交互总览」选择一个交互链。</p><button class="btn ghost" onclick="sv(\'agents-overview\')">返回总览</button></div>';return}try{var chain=await api.g('/l5/interactions/chains/'+chainId);if(!chain){ct.innerHTML='<div class="card"><h3>交互详情</h3><div class="error-banner">交互链不存在</div><button class="btn ghost" onclick="sv(\'agents-overview\')">返回总览</button></div>';return}var records=chain.records||[];var startTs=new Date(chain.start_time*1000).toLocaleString('zh-CN');var dur=chain.total_duration_ms?(chain.total_duration_ms/1000).toFixed(1)+'s':'-';var statusBadge=chain.status==='completed'?'ok':(chain.status==='failed'?'err':'warn');var agentNames={'agent.learning.diagnosis':'学情诊断 Agent','agent.knowledge.generation':'知识生成 Agent','agent.quality.review':'审核校验 Agent','agent.guidance.decision':'导学决策 Agent'};var agentIcons={'agent.learning.diagnosis':'🔍','agent.knowledge.generation':'📝','agent.quality.review':'✅','agent.guidance.decision':'🧭'};var phaseLabels={diagnosis:'诊断阶段',generation:'生成阶段',review:'审核阶段',decision:'决策阶段',feedback:'反馈阶段',system:'系统事件'};var phaseColors={diagnosis:'#3b82f6',generation:'#8b5cf6',review:'#10b981',decision:'#f59e0b',feedback:'#ec4899',system:'#6b7280'};var headerHtml='<div class="card"><h3>🔗 交互链详情</h3><div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:10px"><div class="stat-card"><div class="lbl">提问</div><div style="font-weight:500">'+esc(chain.query||'(无)')+'</div></div><div class="stat-card"><div class="lbl">状态</div><span class="badge '+statusBadge+'" style="font-size:13px;padding:4px 12px">'+esc(chain.status)+'</span></div><div class="stat-card"><div class="lbl">开始时间</div><div>'+startTs+'</div></div><div class="stat-card"><div class="lbl">总耗时</div><div>'+dur+'</div></div><div class="stat-card"><div class="lbl">参与 Agent</div><div>'+chain.agent_count+' 个</div></div><div class="stat-card"><div class="lbl">交互记录</div><div>'+chain.record_count+' 条</div></div></div>'+(chain.final_answer?'<div class="callout">最终回答: '+esc(chain.final_answer)+'</div>':'')+'</div>';var phases=['diagnosis','generation','review','decision'];var flowSteps=phases.map(function(p){var phaseRecords=records.filter(function(r){return r.phase===p});if(!phaseRecords.length)return'';var agentIds=[];phaseRecords.forEach(function(r){if(agentIds.indexOf(r.agent_id)===-1)agentIds.push(r.agent_id)});var agentsHtml=agentIds.map(function(aid){var recs=phaseRecords.filter(function(r){return r.agent_id===aid});var recHtml=recs.map(function(r){var rdur=r.duration_ms?(r.duration_ms/1000).toFixed(1)+'s':'-';var rstatus=r.status==='completed'?'ok':(r.status==='failed'?'err':'warn');return'<div style="padding:6px 0;border-bottom:1px solid var(--rule);font-size:12px"><div style="display:flex;justify-content:space-between"><span style="font-weight:500">'+esc(r.action||'')+'</span><span class="badge '+rstatus+'">'+r.status+'</span></div><div style="color:var(--muted);font-size:11px;margin-top:2px">⏱ '+rdur+'</div>'+(r.input_summary&&Object.keys(r.input_summary).length?'<div style="color:var(--muted);font-size:11px;margin-top:2px">输入: '+esc(JSON.stringify(r.input_summary).slice(0,80))+'</div>':'')+(r.output_summary&&Object.keys(r.output_summary).length?'<div style="color:var(--muted);font-size:11px;margin-top:2px">输出: '+esc(JSON.stringify(r.output_summary).slice(0,80))+'</div>':'')+'</div>'});return'<div style="margin:6px 0;padding:8px;background:var(--surface2);border-radius:6px"><div style="display:flex;align-items:center;gap:6px;margin-bottom:4px"><span>'+(agentIcons[aid]||'🤖')+'</span><span style="font-weight:500;font-size:13px">'+(agentNames[aid]||aid)+'</span></div>'+recHtml+'</div>'}).join('');return'<div class="flow-step" style="border-left:3px solid '+(phaseColors[p]||'#6b7280')+';padding:10px 14px;margin-bottom:10px;background:var(--surface);border-radius:8px;border:1px solid var(--rule)"><div style="display:flex;align-items:center;gap:8px;margin-bottom:8px"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:'+(phaseColors[p]||'#6b7280')+'"></span><h4 style="margin:0;font-size:14px;font-weight:600">'+(phaseLabels[p]||p)+'</h4><span style="color:var(--muted);font-size:11px">('+phaseRecords.length+' 条记录)</span></div>'+agentsHtml+'</div>'}).filter(function(h){return h}).join('');var timelineHtml='<div class="timeline" style="position:relative;padding-left:24px">'+records.filter(function(r){return r.phase!=='system'}).sort(function(a,b){return(a.phase_order||0)-(b.phase_order||0)}).map(function(r,i){var ts=new Date(r.timestamp*1000).toLocaleTimeString('zh-CN');var dur=r.duration_ms?(r.duration_ms/1000).toFixed(1)+'s':'';var statusBadge=r.status==='completed'?'ok':(r.status==='failed'?'err':'warn');var color=phaseColors[r.phase]||'#6b7280';var tos=(r.related_agents&&r.related_agents.length)?r.related_agents.map(function(x){var n=agentNames[x]||String(x).split('.').pop();return n.replace(' Agent','')}).join('、'):'';var passHtml=tos?('<div style="font-size:11px;color:#4b5563;margin-top:3px">📡 传给 <strong>'+esc(tos)+'</strong>'+(r.channel?' <code style="font-size:10px;background:var(--surface2);padding:1px 6px;border-radius:4px;color:#7c3aed">'+esc(r.channel)+'</code>':'')+'</div>'):'';return'<div style="position:relative;padding-bottom:12px;padding-left:16px;border-left:2px solid '+(i<records.length-1?color:'transparent')+'"><div style="position:absolute;left:-6px;top:4px;width:10px;height:10px;border-radius:50%;background:'+color+';border:2px solid var(--surface)"></div><div style="font-size:11px;color:var(--muted)"><span style="background:'+color+'1a;color:'+color+';font-weight:700;padding:0 7px;border-radius:999px;margin-right:6px">第'+(i+1)+'步</span>'+ts+'</div><div style="font-weight:500;font-size:13px">'+(agentNames[r.agent_id]||r.agent_name||r.agent_id)+'</div><div style="font-size:12px;color:var(--muted)">'+esc(r.action||'')+'</div>'+passHtml+'<div style="display:flex;gap:8px;font-size:11px;margin-top:2px">'+(dur?'<span style="color:var(--muted)">⏱ '+dur+'</span>':'')+'<span class="badge '+statusBadge+'">'+r.status+'</span></div></div>'}).join('')+'</div>';ct.innerHTML=headerHtml+'<div class="grid cols-2" style="margin-top:16px"><div class="card"><h4>📋 协作流程（按阶段）</h4><div id="flowSteps">'+flowSteps+'</div></div><div class="card"><h4>⏱ 时序交互线</h4><div id="timeline">'+timelineHtml+'</div></div></div><div class="card" style="text-align:center;margin-top:16px"><button class="btn ghost" onclick="sv(\'agents-overview\')">← 返回交互总览</button></div>';/* 渲染后触发 Mermaid 重绘 */setTimeout(function(){if(typeof mermaid!=='undefined'){document.querySelectorAll('.mermaid').forEach(function(el){try{mermaid.run({nodes:[el]})}catch(e){}})}},800)}catch(e){renderErr(e)}}

/* ---- 画布渲染 (Mermaid.js 图表) ---- */
/* 渲染 Mermaid 图表到指定容器，供知识生成 Agent 的 canvas_generation 工具使用 */
function renderMermaid(containerId, mermaidCode) {
  var el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = '<div class="mermaid">' + esc(mermaidCode) + '</div>';
  if (typeof mermaid !== 'undefined') {
    setTimeout(function() {
      mermaid.run({ nodes: [el.querySelector('.mermaid')] }).catch(function(err) {
        el.innerHTML = '<div class="error-banner">Mermaid 渲染失败: ' + esc(err.message) + '</div>';
      });
    }, 200);
  }
}

/* 生成画布视图 — 直接在知识问答中渲染 Mermaid 代码块 */
function renderCanvasInQuery(queryContainer) {
  /* 查找所有 pre > code.language-mermaid 块并渲染 */
  queryContainer.querySelectorAll('pre code.language-mermaid').forEach(function(codeEl) {
    var mermaidText = codeEl.textContent;
    var pre = codeEl.closest('pre');
    if (!pre) return;
    var container = document.createElement('div');
    container.className = 'canvas-container';
    container.innerHTML = '<div class="mermaid" style="text-align:center">' + esc(mermaidText) + '</div>';
    pre.parentNode.replaceChild(container, pre);
    if (typeof mermaid !== 'undefined') {
      mermaid.run({ nodes: [container.querySelector('.mermaid')] }).catch(function(){});
    }
  });
}

