/* ---- 顶栏接线: 面包屑/健康状态/角色/快捷按钮 ---- */
function bindTopbar(){
  var health=g('healthDot'),healthLabel=g('healthLabel'),roleChip=g('roleChip');
  var loginBtn=g('loginBtn'),themeBtn=g('themeBtn'),settingsBtn=g('settingsBtn');
  // 角色徽章
  function roleText(){return S.tk?(S.r==='student'||S.r==='undergrad'||S.r==='graduate'?'🎓 学习者':'🔐 管理者'):'👥 游客'}
  function syncTopbar(){if(roleChip)roleChip.textContent=roleText();if(loginBtn)loginBtn.textContent=S.tk?'退出':'登录'}
  // 健康状态 (轻量探活, 失败不阻断)
  function probeHealth(){
    api.g('/health').then(function(h){
      var ok=(!h)||h.status==='healthy'||h.status==='ok'||h.overall==='healthy'||h.status===true||h.overall===true||(h.status==null&&h.overall==null);
      if(health){health.className='health-dot'+(ok?'':' warn');health.title=ok?'系统正常':'系统异常'}
      if(healthLabel)healthLabel.textContent=ok?'健康':'异常';
    }).catch(function(){if(health)health.className='health-dot err';if(healthLabel)healthLabel.textContent='离线'})
  }
  if(loginBtn)loginBtn.addEventListener('click',function(){if(S.tk){auth.logout();syncTopbar()}else olv()});
  if(themeBtn)themeBtn.addEventListener('click',function(){tt();themeBtn.textContent=S.th==='dark'?'☀':'🌙'});
  if(settingsBtn)settingsBtn.addEventListener('click',function(){
    d.dispatchEvent(new CustomEvent('dy3-open-model-config'));
  });
  syncTopbar();probeHealth();
}
/* ---- 顶栏导航: 取消一级分组, 二级功能直接平铺到顶栏 ---- */
function renderTopnav(){
  var topnav=g('topnav');
  if(!topnav)return;
  var children=document.querySelectorAll('.sidebar-child');
  if(!children.length){ topnav.innerHTML=''; return; }
  var html='';
  children.forEach(function(c){
    var cIcon=(c.querySelector('.child-icon')||{}).textContent||'';
    var cLabel=c.textContent.replace(cIcon,'').trim();
    var view=c.dataset.view;
    html+='<button class="topnav-item" data-view="'+esc(view)+'"><span class="td-icon">'+cIcon+'</span>'+esc(cLabel)+'</button>';
  });
  topnav.innerHTML=html;
  topnav.querySelectorAll('.topnav-item[data-view]').forEach(function(a){
    a.addEventListener('click',function(e){e.preventDefault();sv(this.dataset.view);});
  });
  highlightTopnav(S.v);
}
