/* ---- 顶栏导航高亮 ---- */
function highlightTopnav(view){
  d.querySelectorAll('.topnav-item[data-view]').forEach(function(a){
    a.classList.toggle('active', a.dataset.view===view);
  });
}
async function init(){var bg=localStorage.getItem('dy3_bg');if(bg)d.documentElement.setAttribute('data-bg',bg);ath();bd();bindTopbar();if(S.tk){try{await auth.me()}catch(e){}}rs();sv('overview');d.addEventListener('sidebar-rebuilt',function(){setTimeout(renderTopnav,50)});setTimeout(renderTopnav,100);}
